#!/usr/bin/env python3
"""
Tests for rendering and installing a resolved keymap into a JetBrains IDE.

    python3 -m unittest discover -s tests
"""

from __future__ import annotations

import shutil
import sys
import tempfile
import unittest
from pathlib import Path
from xml.etree import ElementTree as ET

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import jb_keymap  # noqa: E402

RESOLVED = (
    "<!-- GENERATED by resolve_keymap.py -->\n"
    "<!-- inheritance chain: $default -> macOS -->\n"
    '<keymap version="1" name="macOS">\n'
    '  <action id="Run">\n'
    '    <keyboard-shortcut first-keystroke="ctrl R" />\n'
    "  </action>\n"
    "</keymap>\n"
)


def _tmpdir(case) -> Path:
    d = tempfile.mkdtemp()
    case.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
    return Path(d)


def _resolved_file(case, text: str = RESOLVED, name: str = "macOS.resolved.xml") -> Path:
    p = _tmpdir(case) / name
    p.write_text(text, encoding="utf-8")
    return p


class Naming(unittest.TestCase):
    def test_ported_name_appends_suffix(self):
        self.assertEqual(jb_keymap.ported_name("macOS"), "macOS (ported)")

    def test_target_filename_sanitised(self):
        self.assertEqual(jb_keymap.target_filename("jeffry (x) (ported)"), "jeffry-x-ported.xml")

    def test_read_keymap_name(self):
        self.assertEqual(jb_keymap.read_keymap_name(RESOLVED), "macOS")

    def test_read_keymap_name_single_quoted(self):
        self.assertEqual(jb_keymap.read_keymap_name("<keymap version='1' name='A \"B\"'>"), 'A "B"')

    def test_read_keymap_name_missing_raises_valueerror(self):
        with self.assertRaises(ValueError):
            jb_keymap.read_keymap_name("<keymap version=\"1\"></keymap>")


class Render(unittest.TestCase):
    def test_render_rewrites_only_name(self):
        out, name = jb_keymap.render_ported_xml(RESOLVED)
        self.assertEqual(name, "macOS (ported)")
        self.assertEqual(out, RESOLVED.replace('name="macOS"', 'name="macOS (ported)"'))

    def test_render_quotes_special_characters(self):
        src = '<keymap version="1" name=\'A "B" &amp; C\'>\n</keymap>\n'
        out, name = jb_keymap.render_ported_xml(src)
        self.assertEqual(name, 'A "B" & C (ported)')
        self.assertEqual(ET.fromstring(out).get("name"), 'A "B" & C (ported)')


class FindResolvedFile(unittest.TestCase):
    def test_single_file_is_used(self):
        d = _tmpdir(self)
        (d / "a.resolved.xml").write_text("x")
        (d / "default.xml").write_text("x")
        self.assertEqual(jb_keymap.find_resolved_file(None, d), d / "a.resolved.xml")

    def test_none_found_exits(self):
        with self.assertRaises(SystemExit):
            jb_keymap.find_resolved_file(None, _tmpdir(self))

    def test_several_files_exit_and_list_them(self):
        d = _tmpdir(self)
        (d / "a.resolved.xml").write_text("x")
        (d / "b.resolved.xml").write_text("x")
        with self.assertRaises(SystemExit) as cm:
            jb_keymap.find_resolved_file(None, d)
        self.assertIn("a.resolved.xml", str(cm.exception))
        self.assertIn("b.resolved.xml", str(cm.exception))

    def test_explicit_path_wins(self):
        f = _resolved_file(self)
        self.assertEqual(jb_keymap.find_resolved_file(str(f), _tmpdir(self)), f)

    def test_explicit_missing_exits(self):
        with self.assertRaises(SystemExit):
            jb_keymap.find_resolved_file(str(_tmpdir(self) / "nope.xml"), _tmpdir(self))


class InstallKeymap(unittest.TestCase):
    def test_install_creates_missing_keymaps_dir(self):
        dst_dir = _tmpdir(self) / "keymaps"
        dst = jb_keymap.install_keymap(_resolved_file(self), dst_dir, dry_run=False, stamp="S")
        self.assertEqual(dst, dst_dir / "macOS-ported.xml")
        self.assertEqual(ET.parse(dst).getroot().get("name"), "macOS (ported)")

    def test_install_backs_up_existing_destination(self):
        dst_dir = _tmpdir(self)
        (dst_dir / "macOS-ported.xml").write_text("old", encoding="utf-8")
        dst = jb_keymap.install_keymap(_resolved_file(self), dst_dir, dry_run=False, stamp="S")
        self.assertEqual((dst_dir / "macOS-ported.xml.bak-S").read_text(encoding="utf-8"), "old")
        self.assertIn("macOS (ported)", dst.read_text(encoding="utf-8"))

    def test_install_leaves_source_keymap_untouched(self):
        dst_dir = _tmpdir(self)
        original = dst_dir / "macOS.xml"
        original.write_bytes(b"<keymap name='macOS'/>")
        jb_keymap.install_keymap(_resolved_file(self), dst_dir, dry_run=False, stamp="S")
        self.assertEqual(original.read_bytes(), b"<keymap name='macOS'/>")
        self.assertTrue((dst_dir / "macOS-ported.xml").is_file())

    def test_install_dry_run_writes_nothing(self):
        dst_dir = _tmpdir(self) / "keymaps"
        dst = jb_keymap.install_keymap(_resolved_file(self), dst_dir, dry_run=True, stamp="S")
        self.assertEqual(dst, dst_dir / "macOS-ported.xml")
        self.assertFalse(dst_dir.exists())


if __name__ == "__main__":
    unittest.main()
